CREATE TYPE "ConversationStatus" AS ENUM ('OPEN','PENDING','RESOLVED','CLOSED');
CREATE TYPE "MessageDirection" AS ENUM ('INBOUND','OUTBOUND','INTERNAL');
CREATE TYPE "MessageStatus" AS ENUM ('QUEUED','SENT','DELIVERED','READ','FAILED','RECEIVED');
CREATE TYPE "ChannelProviderKey" AS ENUM ('SIMULATOR','WHATSAPP');
CREATE TABLE "inbox_inboxes" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL, "name" varchar(120) NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE ("organizationId","name"));
CREATE TABLE "crm_contacts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL, "name" varchar(160) NOT NULL, "email" varchar(320), "phone" varchar(40), "company" varchar(160), "avatarUrl" varchar(2048), "source" varchar(80), "notes" text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "crm_contact_channels" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL, "contactId" uuid NOT NULL, "provider" "ChannelProviderKey" NOT NULL, "identifier" varchar(255) NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), UNIQUE ("organizationId","provider","identifier"));
CREATE TABLE "inbox_tags" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL, "name" varchar(80) NOT NULL, "color" varchar(32), "createdAt" timestamptz NOT NULL DEFAULT now(), UNIQUE ("organizationId","name"));
CREATE TABLE "inbox_conversations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL, "inboxId" uuid NOT NULL, "contactId" uuid NOT NULL, "status" "ConversationStatus" NOT NULL DEFAULT 'OPEN', "priority" integer NOT NULL DEFAULT 0, "assigneeMembershipId" uuid, "teamId" uuid, "lastMessageAt" timestamptz, "unreadCount" integer NOT NULL DEFAULT 0, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "inbox_messages" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL, "conversationId" uuid NOT NULL, "externalId" varchar(255), "direction" "MessageDirection" NOT NULL, "status" "MessageStatus" NOT NULL, "body" text, "replyToMessageId" uuid, "metadata" jsonb, "externalOccurredAt" timestamptz, "createdAt" timestamptz NOT NULL DEFAULT now(), UNIQUE ("organizationId","externalId"));
CREATE TABLE "inbox_internal_notes" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL, "conversationId" uuid NOT NULL, "authorMembershipId" uuid NOT NULL, "body" text NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "inbox_channel_accounts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL, "inboxId" uuid NOT NULL, "provider" "ChannelProviderKey" NOT NULL, "displayName" varchar(120) NOT NULL, "externalAccountId" varchar(255), "encryptedConfig" jsonb, "enabled" boolean NOT NULL DEFAULT true, "createdAt" timestamptz NOT NULL DEFAULT now(), UNIQUE ("organizationId","provider","externalAccountId"));
CREATE TABLE "inbox_channel_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL, "channelAccountId" uuid NOT NULL, "externalId" varchar(255) NOT NULL, "type" varchar(100) NOT NULL, "receivedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE ("organizationId","channelAccountId","externalId"));
CREATE INDEX "crm_contacts_org_name" ON "crm_contacts" ("organizationId","name");
CREATE INDEX "inbox_conversations_queue" ON "inbox_conversations" ("organizationId","status","lastMessageAt" DESC);
CREATE INDEX "inbox_messages_timeline" ON "inbox_messages" ("organizationId","conversationId","createdAt");
CREATE INDEX "inbox_notes_timeline" ON "inbox_internal_notes" ("organizationId","conversationId","createdAt");
CREATE INDEX "contact_channels_contact" ON "crm_contact_channels" ("organizationId","contactId");
ALTER TABLE "inbox_conversations" ADD CONSTRAINT "inbox_conversations_org_id_key" UNIQUE ("organizationId", "id");
ALTER TABLE "crm_contact_channels" ADD CONSTRAINT "crm_contact_channels_contact_fk" FOREIGN KEY ("contactId") REFERENCES "crm_contacts"("id") ON DELETE CASCADE;
ALTER TABLE "inbox_conversations" ADD CONSTRAINT "inbox_conversations_inbox_fk" FOREIGN KEY ("inboxId") REFERENCES "inbox_inboxes"("id") ON DELETE RESTRICT;
ALTER TABLE "inbox_conversations" ADD CONSTRAINT "inbox_conversations_contact_fk" FOREIGN KEY ("contactId") REFERENCES "crm_contacts"("id") ON DELETE RESTRICT;
ALTER TABLE "inbox_messages" ADD CONSTRAINT "inbox_messages_conversation_fk" FOREIGN KEY ("conversationId") REFERENCES "inbox_conversations"("id") ON DELETE CASCADE;
ALTER TABLE "inbox_internal_notes" ADD CONSTRAINT "inbox_notes_conversation_fk" FOREIGN KEY ("conversationId") REFERENCES "inbox_conversations"("id") ON DELETE CASCADE;
ALTER TABLE "inbox_channel_accounts" ADD CONSTRAINT "inbox_channel_accounts_inbox_fk" FOREIGN KEY ("inboxId") REFERENCES "inbox_inboxes"("id") ON DELETE CASCADE;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['inbox_inboxes','crm_contacts','crm_contact_channels','inbox_tags','inbox_conversations','inbox_messages','inbox_internal_notes','inbox_channel_accounts','inbox_channel_events'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING ("organizationId" = current_setting(''app.current_organization_id'', true)::uuid) WITH CHECK ("organizationId" = current_setting(''app.current_organization_id'', true)::uuid)',t); END LOOP; END $$;
